// Five real-shaped ads so "Manual Test" produces a finished brief before you connect anything.
// Delete this node once the scheduled path works, or keep it to re-test after editing the rules.
return [
  { json: { adBody: 'Get 60% off your first box. Free delivery, cancel anytime. Chef-designed meals in 15 minutes.' } },
  { json: { adBody: 'Limited time: 50% off your first 2 boxes. No commitment, skip any week. Ready in 20 minutes.' } },
  { json: { adBody: 'Save $90 across your first month. Free shipping on every box. Dinner done in under 15 minutes.' } },
  { json: { adBody: 'Tired of deciding what to cook? 40% off to start. Cancel whenever. Meals in 15 minutes flat.' } },
  { json: { adBody: 'Your first box is free. Just pay shipping. Skip a week anytime, no questions, no commitment.' } },
];

// What forty advertisers keep saying is a fact you can count. No model needed, and no API key.
// Three passes: the offer shapes (regex), the phrases that recur, and the promises they make.
const STOP = new Set(['the','and','you','your','for','with','get','our','are','all','new','now','from','that','this','out','off','has','have','can','will','was','not','but','how','why','who','its','it\'s','a','i','to','in','of','on','is','at','be','or','we','us','my','me','do','if','so','up','no','yes','more','most','just','only','than','then','into','over','when','what','they','their','them','there','here','also','any','one','two']);

const ads = [];
for (const item of $input.all()) {
  const copy = String(item.json.adBody || item.json.body || item.json.text || item.json.description || '').replace(/\s+/g, ' ').trim();
  if (copy) ads.push(copy);
}
if (!ads.length) return [];

// 1. Offer shapes — the concrete thing being given away.
const OFFERS = [
  ['percentage discount', /\b(\d{1,2})\s*%\s*(off|discount)/gi],
  ['money off', /\b(save|off)\s*[$£€]\s?\d+/gi],
  ['free item', /\bfree\s+(box|trial|delivery|shipping|month|week|gift|sample)/gi],
  ['first-order hook', /\bfirst\s+(box|order|month|week|purchase)/gi],
  ['no commitment', /\b(cancel anytime|no commitment|skip any|cancel whenever|no contract)/gi],
  ['speed claim', /\b\d{1,3}\s*(minute|min|second)s?\b/gi],
  ['urgency', /\b(limited time|today only|ends (soon|tonight|friday)|last chance|while stocks)/gi],
];
const offers = [];
for (const [label, re] of OFFERS) {
  let n = 0;
  const examples = [];
  for (const ad of ads) {
    const m = ad.match(re);
    if (m) { n += 1; if (examples.length < 2) examples.push(m[0]); }
  }
  if (n) offers.push({ offer: label, adsUsingIt: n, share: Math.round((n / ads.length) * 100), examples });
}
offers.sort((a, b) => b.adsUsingIt - a.adsUsingIt);

// 2. Phrases that recur across DIFFERENT ads — two- and three-word runs, counted once per ad so one
// repetitive advertiser cannot manufacture a trend on its own.
const phraseAds = new Map();
for (const ad of ads) {
  const words = ad.toLowerCase().replace(/[^a-z0-9$%\s]/g, ' ').split(/\s+/).filter(Boolean);
  const seen = new Set();
  for (let n = 2; n <= 3; n += 1) {
    for (let i = 0; i + n <= words.length; i += 1) {
      const run = words.slice(i, i + n);
      if (run.every((w) => STOP.has(w))) continue;
      seen.add(run.join(' '));
    }
  }
  for (const p of seen) phraseAds.set(p, (phraseAds.get(p) || 0) + 1);
}
const cfg = $('Who you are watching').first()?.json || {};
const floor = Math.max(2, Number(cfg.minRepeats) || 3);
const phrases = [...phraseAds.entries()]
  .filter(([, n]) => n >= floor)
  .sort((a, b) => b[1] - a[1] || b[0].length - a[0].length)
  .slice(0, 12)
  .map(([phrase, n]) => ({ phrase, adsUsingIt: n }));

return [{ json: { adsRead: ads.length, offers, phrases, openingLines: ads.map((a) => a.split(/[.!?]/)[0].trim()).filter(Boolean).slice(0, 8) } }];

// One flat row per week, so a year of these is a readable sheet rather than nested JSON.
const d = $json;
const pct = (o) => o.offer + ' (' + o.share + '% of ads)';
return [{
  json: {
    week: new Date().toISOString().slice(0, 10),
    ads_read: d.adsRead,
    top_offers: (d.offers || []).slice(0, 4).map(pct).join(' · ') || 'none detected',
    offer_examples: (d.offers || []).slice(0, 4).flatMap((o) => o.examples).join(' | '),
    recurring_phrases: (d.phrases || []).map((p) => p.phrase + ' (' + p.adsUsingIt + ')').join(' · ') || 'nothing repeated above the floor',
    opening_lines: (d.openingLines || []).join('\n'),
  },
}];
